import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))+"/out")
from h18 import *
"""Ynmo Flow phase 4: comments and @mentions, work log and estimate, attachments: cascade delete, ticket links, sorting, labels and due dates, product and Monthly card, bug and report fields, quick create, shortcuts, saved filters, bulk edit, workflow designer (rules, reasons), key repair. Fake test database only."""
import json
R=[]
def ok(n,c): R.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as pw:
    b=pw.chromium.launch(); ctx=mkctx(b); errs=[]
    A=newpage(ctx,errs); signup(A,'Admin','adm@x.com')
    A.evaluate("""()=>{const s=JSON.parse(localStorage.getItem('fk3'));s.flow_comments.old={iss:'t1',by:'Omar',at:'2026-11-01T08:00:00.000Z',t:'Earlier note from Omar',men:[]};s.flow_issues.t1={key:'YNMO-1',n:1,rk:10,type:'task',t:'Pay by card',d:'',st:'open',pr:'medium',as:'',rp:'Omar',par:'',ep:'',pts:null,lb:[],bl:'',sp:'',prod:'',card:'',sev:'',env:'',steps:'',rn:'',req:'',oe:null,cr:'2026-11-01T08:00:00.000Z',up:'2026-11-01T08:00:00.000Z',hist:[{at:'2026-11-01T08:00:00.000Z',by:'Omar',f:'created',a:'',b:'YNMO-1'}]};localStorage.setItem('fk3',JSON.stringify(s))}""")
    A.reload(); A.wait_for_timeout(2200); A.click('#nav button[data-p="flow"]'); A.wait_for_timeout(300); A.click('.flowitem[data-view="issues"]'); A.wait_for_timeout(300)
    A.locator('.flowrow',has_text='Pay by card').click(); A.wait_for_timeout(300)
    ok('A1 the ticket window has Attachments, Comments and Work log', A.locator('#fi-files').count()==1 and A.locator('#fi-thread .ftab').count()==2 and 'Comments (1)' in A.locator('#fi-thread').inner_text())
    ok('A2 an existing comment shows its author', 'Omar' in A.locator('.fcm').first.inner_text() and 'Earlier note' in A.locator('.fcm').first.inner_text())
    A.fill('#fi-cm',''); A.click('#fi-cm-send'); A.wait_for_timeout(150)
    ok('A3 an empty comment is refused with a message', 'Write something' in A.locator('#fi-cm-err').inner_text())
    M=A.locator('#fi-mention option').nth(1).get_attribute('value'); A.select_option('#fi-mention',M); A.wait_for_timeout(100)
    ok('A4 the @ picker puts @Name in the text', A.locator('#fi-cm').input_value().startswith('@'+M))
    A.fill('#fi-cm','@'+M+' can you confirm the bank API date?'); A.click('#fi-cm-send'); A.wait_for_timeout(300)
    ok('A5 the comment is posted by me with the mention listed', A.locator('.fcm').count()==2 and ('Mentioned: '+M) in A.locator('.fcm').last.inner_text() and 'Admin' in A.locator('.fcm').last.inner_text())
    A.locator('.fcm').last.locator('button[data-act="editcm"]').click(); A.wait_for_timeout(150); A.locator('.fcmedit').fill('Edited text'); A.click('button[data-act="savecm"]'); A.wait_for_timeout(300)
    ok('A6 edit my comment: text changes and it says edited', 'Edited text' in A.locator('.fcm').last.inner_text() and 'edited' in A.locator('.fcm').last.inner_text())
    ok('A7 Admin (can delete) may delete Omar\'s comment; edit is only for own', A.locator('.fcm').first.locator('button[data-act="delcm"]').count()==1 and A.locator('.fcm').first.locator('button[data-act="editcm"]').count()==0)
    A.reload(); A.wait_for_timeout(2200); A.click('#nav button[data-p="flow"]'); A.wait_for_timeout(300); A.click('.flowitem[data-view="issues"]'); A.wait_for_timeout(300); A.locator('.flowrow',has_text='Pay by card').click(); A.wait_for_timeout(300)
    ok('A8 comments survive a reload', A.locator('.fcm').count()==2 and 'Edited text' in A.locator('#fi-thread').inner_text())
    A.locator('.fcm').first.locator('button[data-act="delcm"]').click(); A.wait_for_timeout(300)
    ok('A9 delete a comment', A.locator('.fcm').count()==1)
    # estimate and work log
    A.fill('#fi-oe','abc'); A.click('#fi-save'); A.wait_for_timeout(250)
    ok('A10 a bad estimate is refused and the window stays open', A.locator('#fi-oe').count()==1)
    A.fill('#fi-oe','1d'); A.click('#fi-save'); A.wait_for_timeout(400)
    A.locator('.flowrow',has_text='Pay by card').click(); A.wait_for_timeout(300); A.click('#fi-thread .ftab[data-tab="log"]'); A.wait_for_timeout(200)
    ok('A11 the estimate is saved and shown in the Work log tab', '1d' in A.locator('.ftime').inner_text() and 'Logged 0m' in A.locator('.ftime').inner_text() and 'Remaining 1d' in A.locator('.ftime').inner_text())
    A.fill('#fi-log-time','nonsense'); A.click('#fi-log-add'); A.wait_for_timeout(150)
    ok('A12 bad time is refused with an example', '2h 30m' in A.locator('#fi-log-err').inner_text())
    A.fill('#fi-log-time','3h'); A.fill('#fi-log-note','Wired the form'); A.click('#fi-log-add'); A.wait_for_timeout(300)
    ok('A13 logging 3h: logged 3h, remaining 5h, one entry', 'Logged 3h' in A.locator('.ftime').inner_text() and 'Remaining 5h' in A.locator('.ftime').inner_text() and A.locator('.flog').count()==1 and 'Wired the form' in A.locator('.flog').inner_text())
    A.fill('#fi-log-time','1d'); A.click('#fi-log-add'); A.wait_for_timeout(300)
    ok('A14 going over the estimate is shown in red words (Over by)', 'Over by 3h' in A.locator('.ftime').inner_text())
    A.locator('.flog').first.locator('button[data-act="dellog"]').click(); A.wait_for_timeout(300)
    ok('A15 delete a log entry', A.locator('.flog').count()==1 and 'Logged 3h' in A.locator('.ftime').inner_text())
    ok('A16 history shows the estimate change in readable time', '1d' in A.locator('.flowhist').inner_text() and 'original estimate' in A.locator('.flowhist').inner_text())
    # files
    A.set_input_files('#fi-file',[{'name':'notes.txt','mimeType':'text/plain','buffer':b'hello flow'}]); A.wait_for_timeout(600)
    ok('A17 attach a file: listed with size and author', A.locator('.fatrow').count()==1 and 'notes.txt' in A.locator('.fatrow').inner_text() and 'Attachments (1)' in A.locator('#fi-files').inner_text())
    A.set_input_files('#fi-file',[{'name':'run.exe','mimeType':'application/octet-stream','buffer':b'MZ'}]); A.wait_for_timeout(500)
    ok('A18 a blocked type is refused and nothing is added', A.locator('.fatrow').count()==1)
    A.set_input_files('#fi-file',[{'name':'big.pdf','mimeType':'application/pdf','buffer':b'x'*(10*1024*1024+1)}]); A.wait_for_timeout(700)
    ok('A19 a file over 10 MB is refused', A.locator('.fatrow').count()==1)
    stored=A.evaluate("Object.keys(JSON.parse(localStorage.getItem('fk3files')||'{}')).length")
    ok('A20 only the good file reached storage', stored==1)
    A.reload(); A.wait_for_timeout(2200); A.click('#nav button[data-p="flow"]'); A.wait_for_timeout(300); A.click('.flowitem[data-view="issues"]'); A.wait_for_timeout(300); A.locator('.flowrow',has_text='Pay by card').click(); A.wait_for_timeout(300)
    ok('A21 the file is still there after a reload', A.locator('.fatrow').count()==1)
    A.click('button[data-act="rmfile"]'); A.wait_for_timeout(500)
    ok('A22 remove the file: record and stored copy are gone', A.locator('.fatrow').count()==0 and A.evaluate("Object.keys(JSON.parse(localStorage.getItem('fk3files')||'{}')).length")==0)
    A.evaluate("window.__storageFail=true"); A.set_input_files('#fi-file',[{'name':'again.txt','mimeType':'text/plain','buffer':b'abc'}]); A.wait_for_timeout(500)
    ok('A23 storage down: nothing is added and the page still works', A.locator('.fatrow').count()==0 and A.locator('#fi-cm').count()==1)
    ok('A24 no script errors', not errs)
    if errs: print(errs)
    b.close()
bad=[n for n,c in R if not c]; print('TOTAL',len(R),'PASS',len(R)-len(bad),'FAIL',len(bad)); sys.exit(1 if bad else 0)
